    // ---------- Estado da operação ----------
    private string StatusMessage = "";
    private bool IsDownloading = false;
    private int RetryDelayMs = 5000;            // 5 s inicial
    private const int MaxRetryDelayMs = 5000;   // nunca ultrapassa 5 s
    private bool FileNotFoundError = false;

    // ---------- Caminhos ----------
    private string PatchLuaPath =>
        Path.Combine(Environment.ContentRootPath, "patch", "patch.lua");
    private string DownloadFolder =>
