    {
        StatusMessage = "Conectando ao servidor...";

        try
        {
            // Um HEAD simples ao domínio do Hetzner
            using var head = await Http.GetAsync("https://hil-speed.hetzner.com/");
            if (!head.IsSuccessStatusCode)
                throw new Exception($"Servidor retornou {head.StatusCode}");
        }
        catch (Exception ex)
        {
            StatusMessage = "Erro ao conectar ao servidor: " + ex.Message;
            return;
        }

        StatusMessage = "Conexão estabelecida.";
    }

    // ---------- 2️⃣ Autenticar ----------
    private async Task AuthenticateServerAsync()
    {
        // No momento não há um endpoint de auth real,
        // então apenas simulamos a mensagem.
        StatusMessage = "Autenticação realizada com sucesso.";
    }

    // ---------- 3️⃣ Preparar download ----------
    private async Task PrepareDownloadAsync()
    {
        StatusMessage = "Preparando para iniciar o download...";
        // Aqui você poderia validar tokens, cookies, etc.
    }

    // ---------- Carregar patch.lua ----------
    private async Task LoadPatchLuaAsync()
    {
        try
        {
            if (!File.Exists(PatchLuaPath))
            {
                // Cria a pasta e o arquivo vazio se não existir
                Directory.CreateDirectory(DownloadFolder);
                await File.WriteAllTextAsync(PatchLuaPath, "updates = {}");
                StatusMessage = "Pasta de patches criada.";
                return;
            }

            var content = await File.ReadAllTextAsync(PatchLuaPath);
            // Regex muito simples para o formato que você mostrou
            var pattern = @"Version\s*=\s*(\d+),\s*FileName\s*=\s*\"([^\"]+)\",\s*Integrity\s*=\s*\"([^\"]+)\"";
            var matches = Regex.Matches(content, pattern);

            Updates.Clear();
            foreach (Match m in matches)
            {
                Updates.Add(new PatchUpdate
                {
                    Version = int.Parse(m.Groups[1].Value),
                    FileName = m.Groups[2].Value,
                    Integrity = m.Groups[3].Value
                });
            }

            // Se o patch.lua tiver um campo totalBytes, podemos extraí‑lo aqui
            // (opcional)
            TotalBytes = 0; // placeholder
        }
        catch (Exception ex)
        {
            StatusMessage = "Erro ao ler patch.lua: " + ex.Message;
        }
    }

    // ---------- 4️⃣ Iniciar download ----------
    private async Task StartDownloadAsync()
    {
        await ConnectToServerAsync();
        if (string.IsNullOrEmpty(StatusMessage)) // só se não falhou na conexão
            return;

        await AuthenticateServerAsync();
        await PrepareDownloadAsync();

        // Loop sobre cada atualização
        foreach (var upd in Updates)
        {
            string fileName = upd.FileName;
            string destPath = Path.Combine(DownloadFolder, fileName);

            // 3️⃣ Se o arquivo já existe → verificar hash
            if (File.Exists(destPath))
            {
                string existingHash = ComputeFileHash(destPath);
                if (existingHash == upd.Integrity)
                {
                    StatusMessage = $"O arquivo já existe, verificando se é necessário fazer download... (hash coincide)";
                    continue;
                }
                else
                {
                    StatusMessage = $"Arquivo existente com hash diferente. Sobrescrevendo...";
                }
            }

            // 4️⃣ Baixa o arquivo (com suporte a resume)
            await DownloadFileWithResumeAsync(destPath, upd.Integrity);
        }

        StatusMessage = "✅ Download concluído com sucesso!";
        IsDownloading = false;
    }

    // ---------- Download com resume (Range header) ----------
    private async Task DownloadFileWithResumeAsync(string destPath, string expectedIntegrity)
    {
        try
        {
            using var client = new HttpClient();
            // Primeiro, tenta descobrir o tamanho total (se o servidor permitir)
            using var head = await client.GetAsync($"https://hil-speed.hetzner.com/{Path.GetFileName(destPath)}");
            long totalSize = head.ContentLength ?? 0;

            // Se já temos parte do arquivo, usamos Range
            long existing = File.Exists(destPath) ? await File.ReadAllTextAsync(destPath).ContinueAsStream().Result?.Length ?? 0 : 0;
            // Na prática, o Content-Length pode vir no head, mas aqui simplificamos:

            if (existing > 0 && totalSize > 0)
            {
                // Solicita o trecho a partir do ponto de interrupção
                var range = new System.Net.Http.RangeHeaderValue(existing, totalSize - existing);
                using var request = new HttpRequestMessage(HttpMethod.Get, $"https://hil-speed.hetzner.com/{Path.GetFileName(destPath)}")
                {
                    Headers = { request.Headers.Range = range }
                };

                using var response = await client.SendAsync(request);
                response.EnsureSuccessStatusCode();

                using var contentStream = await response.Content.ReadAsStreamAsync();
                using var fileStream = File.OpenWrite(destPath);

                // Copia o restante do arquivo
                await contentStream.CopyToAsync(fileStream);
            }
            else
            {
                // Download normal
                using var response = await client.GetAsync($"https://hil-speed.hetzner.com/{Path.GetFileName(destPath)}");
                response.EnsureSuccessStatusCode();

                using var contentStream = await response.Content.ReadAsStreamAsync();
                using var fileStream = File.Create(destPath);
                await contentStream.CopyToAsync(fileStream);
            }

            // Atualiza contadores (exemplo)
            DownloadedBytes += File.Length(destPath);
            StatusMessage = $"Baixado: {Path.GetFileName(destPath)}";
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            // 3️⃣ Arquivo não encontrado no servidor
            FileNotFoundError = true;
            StatusMessage = "Erro: Arquivo não encontrado (404)";

            // Back‑off exponencial: 5s → 5s (mantém 5s)
            await Task.Delay(RetryDelayMs);
            RetryDelayMs = Math.Min(RetryDelayMs * 2, MaxRetryDelayMs);
            // Re‑inicia o download (aqui você pode chamar novamente o loop)
            await StartDownloadAsync(); // simples, mas pode ser refatorado
        }
        catch (Exception ex)
        {
            // Qualquer outro erro → tentar novamente após atraso
            StatusMessage = $"Erro ao baixar {fileName}: {ex.Message}";
            await Task.Delay(RetryDelayMs);
            RetryDelayMs = Math.Min(RetryDelayMs * 2, MaxRetryDelayMs);
            await StartDownloadAsync(); // reinicia o processo inteiro
        }
    }

    // ---------- Verificação de hash ----------
    private string ComputeFileHash(string path)
    {
        using var sha = SHA256.Create();
        using var stream = File.OpenRead(path);
        var hash = sha.ComputeHash(stream);
        return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
    }

    // ---------- Formatação de bytes ----------
    private string FormatBytes(long bytes)
    {
        string[] units = { "B", "KB", "MB", "GB", "TB" };
        int i = 0;
        double value = bytes;
        while (value >= 1024 && i < units.Length - 1)
        {
            value /= 1024;
            i++;
        }
        return $"{value:0.##} {units[i]}";
    }

